/** 명세서 기준 앱 내 알림 조회·읽음 처리 API입니다. */
package com.dandimate.durooduroo.notification.controller;
import com.dandimate.durooduroo.common.api.ApiResponse; import com.dandimate.durooduroo.common.auth.MemberTokenResolver; import com.dandimate.durooduroo.common.exception.BusinessException; import com.dandimate.durooduroo.member.repository.MemberRepository; import com.dandimate.durooduroo.notification.repository.NotificationRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController public class NotificationController { private final NotificationRepository notifications; private final MemberRepository members; public NotificationController(NotificationRepository n,MemberRepository m){notifications=n;members=m;}
 @GetMapping("/api/v1/rooms/{roomId}/notifications") public ApiResponse<?> list(@PathVariable String roomId,@RequestHeader(required=false) String authorization,@RequestParam(required=false) String memberToken){String token=MemberTokenResolver.resolve(authorization,memberToken);var me=members.findByRoomIdAndMemberToken(roomId,token).orElseThrow(()->new BusinessException("MEMBER_FORBIDDEN","참여자만 알림을 조회할 수 있습니다."));var list=notifications.findAllByMemberIdOrderByCreatedAtDesc(me.getId()).stream().map(n->Map.of("id",n.getId(),"type",n.getType(),"resourceType",n.getResourceType(),"resourceId",n.getResourceId(),"readAt",n.getReadAt()==null?"":n.getReadAt().toString(),"createdAt",n.getCreatedAt())).toList();return ApiResponse.success(Map.of("notifications",list));}
 @PostMapping("/api/v1/notifications/{notificationId}/read") public ApiResponse<?> read(@PathVariable String notificationId,@RequestHeader(required=false) String authorization,@RequestParam(required=false) String memberToken){var n=notifications.findById(notificationId).orElseThrow(()->new BusinessException("NOTIFICATION_NOT_FOUND","알림이 없습니다."));String token=MemberTokenResolver.resolve(authorization,memberToken);var me=members.authenticate(token);if(!me.getId().equals(n.getMemberId()))throw new BusinessException("FORBIDDEN","본인 알림만 읽을 수 있습니다.");n.read();notifications.save(n);return ApiResponse.success(Map.of("id",n.getId(),"read",true));}
}
